let selected=null,hash=null,runId=null;async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||r.statusText);return j}function msg(e){document.querySelector('#status').textContent=e.message;setTimeout(()=>document.querySelector('#status').textContent='Ready',5000)}async function loadFiles(){try{let j=await api('files?path='+encodeURIComponent(document.querySelector('#dir').value));document.querySelector('#files').innerHTML=j.items.map(x=>`<div class="file ${selected===x.path?'selected':''}" onclick="${x.directory?`document.querySelector('#dir').value='${esc(x.path)}';loadFiles()`:`openFile('${esc(x.path)}')`}">${x.directory?'📁':'📄'} ${esc(x.name)}</div>`).join('')||'<span class="muted">Empty folder</span>'}catch(e){msg(e)}}function esc(x){return x.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll("'",'&#39;')}async function openFile(p){try{let x=await api('file?path='+encodeURIComponent(p));selected=x.path;hash=x.sha256;document.querySelector('#opened').textContent=x.path+' · '+x.encoding+' · '+x.newline;document.querySelector('#editor').value=x.content;loadFiles()}catch(e){msg(e)}}async function saveFile(){if(!selected){msg(Error('Create a file first'));return}try{let j=await api('file','PUT',{path:selected,content:document.querySelector('#editor').value,expected_hash:hash});hash=j.sha256;msg(Error('Saved '+selected));loadFiles()}catch(e){msg(e)}}function newFile(){let p=prompt('New file path (relative to workspace)');if(p){selected=p;hash=null;document.querySelector('#opened').textContent=p+' · new';document.querySelector('#editor').value=''}}async function previewDiff(){if(!selected||!hash)return msg(Error("Open an existing file first"));try{let j=await api("diff","POST",{path:selected,content:document.querySelector("#editor").value});document.querySelector("#terminal").textContent=j.diff||"No changes"}catch(e){msg(e)}}function discardEdit(){if(selected)openFile(selected)}async function newFolder(){let path=prompt("New folder path");if(path)try{await api("mkdir","POST",{path});loadFiles()}catch(e){msg(e)}}async function renameFile(){if(!selected)return msg(Error("Select a file first"));let destination=prompt("Move/rename to path",selected);if(destination)try{await api("move","POST",{source:selected,destination});selected=destination;openFile(destination)}catch(e){msg(e)}}async function deleteFile(){if(!selected)return;let confirmation=prompt("A backup will be created. Type DELETE to confirm");if(confirmation==="DELETE")try{let r=await api("delete","POST",{path:selected,approved:true});msg(Error("Backed up to "+r.backup));selected=null;loadFiles()}catch(e){msg(e)}}async function runTests(){try{let j=await api("tests/run","POST",{});document.querySelector("#terminal").textContent=JSON.stringify(j,null,2)}catch(e){msg(e)}}async function pollRun(){if(!runId)return;try{let r=await api("runs/"+runId);document.querySelector("#terminal").textContent=`${r.status} (exit ${r.exit_code})
${r.stdout}
${r.stderr}`;if(r.status==="running")setTimeout(pollRun,300)}catch(e){msg(e)}}async function stopRun(){if(runId)try{await api("run","DELETE",{id:runId})}catch(e){msg(e)}}async function search(){try{let mode=document.querySelector('#mode').value,j=await api('search','POST',{query:document.querySelector('#query').value,regex:mode==='regex',filename:mode==='filename'});document.querySelector('#results').innerHTML=j.results.map(x=>`<div class="item" onclick="openFile('${esc(x.path)}')"><b>${esc(x.path)}:${x.line}</b><br>${esc(x.excerpt)}</div>`).join('')||'No matches'}catch(e){msg(e)}}async function runCmd(){let command=document.querySelector('#command').value;if(!command)return;document.querySelector('#terminal').textContent='Running…
';try{let r=await api('command','POST',{command,cwd:document.querySelector('#cwd').value,shell:document.querySelector('#shell').value,timeout:120,approved:/ (?:rm\s+-rf|rmdir\s+/s|del\s+/s|format|shutdown|diskpart|git\s+reset\s+--hard|Remove-Item) /i.test(command)?window.confirm('This command can make destructive changes. Continue?'):false});runId=r.id;document.querySelector('#terminal').textContent=`${r.status}
${r.stdout}
${r.stderr}`;pollRun()}catch(e){document.querySelector('#terminal').textContent=e.message}document.querySelector('#command').value=''}async function showGit(){try{let j=await api('git?args=status%20--short%20--branch');document.querySelector('#terminal').textContent=j.stdout+j.stderr||`exit ${j.exit_code}`}catch(e){msg(e)}}async function showTests(){try{let j=await api('tests');document.querySelector('#terminal').textContent=JSON.stringify(j,null,2)}catch(e){msg(e)}}async function refreshContext(){try{let j=await api('context','POST',{});document.querySelector('#context').textContent=JSON.stringify(j,null,2)}catch(e){msg(e)}}async function startModelAgent(){try{let j=await api("agent/model","POST",{task:document.querySelector("#task").value,model:document.querySelector("#model").value||undefined,base_url:document.querySelector("#modelurl").value||undefined,api_key:document.querySelector("#modelkey").value||undefined});document.querySelector("#activity").textContent=JSON.stringify(j)}catch(e){msg(e)}}async function startAgent(){try{let j=await api('agent/plan','POST',{task:document.querySelector('#task').value});document.querySelector('#activity').innerHTML='<div class="item">'+esc(JSON.stringify(j))+'</div>';refreshContext()}catch(e){msg(e)}}async function stopAgent(){try{await api('agent/stop','POST',{});msg(Error('Stop requested'))}catch(e){msg(e)}}async function poll(){try{let s=await api('agent/state');if(s.status==='running'||s.steps?.length)document.querySelector('#activity').innerHTML='<div class="item">'+esc(JSON.stringify(s,null,2))+'</div>'}catch{}}document.querySelector('#root').textContent=location.origin;api('model/status').then(x=>{document.querySelector('#modelstatus').textContent=x.configured?(x.model+' @ '+x.base_url):'not configured';if(x.configured){document.querySelector('#model').value=x.model||'';document.querySelector('#modelurl').value=x.base_url||''}}).catch(()=>{});loadFiles();refreshContext();setInterval(poll,2000);
